                }
            }
            if ($this->collWfInstanciaBitacoras) {
                foreach ($this->collWfInstanciaBitacoras as $o) {
                    $o->clearAllReferences($deep);
                }
            }
            if ($this->aWfActividadTransicion instanceof Persistent) {
              $this->aWfActividadTransicion->clearAllReferences($deep);
            }
            if ($this->aUsuario instanceof Persistent) {
              $this->aUsuario->clearAllReferences($deep);
            }
            if ($this->aComInterna instanceof Persistent) {
              $this->aComInterna->clearAllReferences($deep);
